import React from 'react';

import styles from '../../css/Header-viewer.module.css'

const HeaderViewer = () => {
  return (
    <>
      <div className={styles.content}>
        <div className={styles['image-box']}>
          <img src="" alt="" />
        </div>
      </div>
    </>
  );
}

export default HeaderViewer;
